for a, b in flights:
    graph[a].append(b)

# Perform a DFS to find if there's a path from 1 to n
def dfs(node, visited):
    if node == n:
        return True
    visited.add(node)
    for neighbor in graph[node]:
        if neighbor not in visited:
            if dfs(neighbor, visited):
                return True
    return False

visited = set()
if not dfs(1, visited):
    print("No")
else:
    print("Yes")
    # Assign 1 to all flights on the path from 1 to n
    path = []
    def dfs_path(node, path):
        if node == n:
            path.append(node)
            return True
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                if dfs_path(neighbor, path):
                    path.append(node)
                    return True
        return False

    dfs_path(1, path)
    path.reverse()

    # Assign 1 to all edges on the path, and 2 to all others
    flight_duration = {tuple(sorted((a, b))): 1 for a, b in flights}
    for i in range(len(path) - 1):
        a, b = path[i], path[i + 1]
        flight_duration[(a, b)] = 2

    for a, b in flights:
